import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor convtranspose3d_forward(torch::Tensor x,
                                       torch::Tensor weight,
                                       c10::optional<torch::Tensor> bias,
                                       int stride, int padding, int output_padding,
                                       int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled ConvTranspose3d kernel (groups=1).
// Each block computes a spatial tile of output for a fixed (n, co).
// Weight slice for this co (shape Cin x K x K x K) is cached in shared memory.
template <typename T, int Threads, int PVec>
__global__ void convtranspose3d_kernel(
    const T* __restrict__ X,   // [N, Cin, D, H, W]
    const T* __restrict__ Wt,  // [Cin, Cout, K, K, K]
    const T* __restrict__ Bs,  // [Cout] or nullptr
    T* __restrict__ Y,         // [N, Cout, Dout, Hout, Wout]
    int N, int Cin, int D, int H, int Win,
    int Cout, int K, int stride, int padding,
    int Dout, int Hout, int Wout)
{
    const int tid = threadIdx.x;

    const int n  = blockIdx.z;
    const int co = blockIdx.y;

    const int P_total = Dout * Hout * Wout;
    const int PTile   = Threads * PVec;
    const int p_block = blockIdx.x * PTile;

    // Strides for X (per-batch slice)
    const int64_t sXn = (int64_t)Cin * D * H * Win;
    const int64_t sXc = (int64_t)D * H * Win;
    const int64_t sXd = (int64_t)H * Win;
    const int64_t sXh = (int64_t)Win;

    const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
    const int64_t sYc = (int64_t)Dout * Hout * Wout;
    const int64_t sYd = (int64_t)Hout * Wout;
    const int64_t sYh = (int64_t)Wout;

    // Global tensors via CuTe
    Tensor mX = make_tensor(
        make_gmem_ptr(X + (int64_t)n * sXn),
        make_shape(Cin, D, H, Win),
        make_stride(sXc, sXd, sXh, Int<1>{})
    );

    Tensor mY = make_tensor(
        make_gmem_ptr(Y + (int64_t)n * sYn + (int64_t)co * sYc),
        make_shape(Dout, Hout, Wout),
        make_stride(sYd, sYh, Int<1>{})
    );

    // Weight tensor: [Cin, Cout, K, K, K]
    const int64_t sWci = (int64_t)Cout * K * K * K;
    const int64_t sWco = (int64_t)K * K * K;
    const int64_t sWkd = (int64_t)K * K;
    const int64_t sWkh = (int64_t)K;

    Tensor mW = make_tensor(
        make_gmem_ptr(Wt),
        make_shape(Cin, Cout, K, K, K),
        make_stride(sWci, sWco, sWkd, sWkh, Int<1>{})
    );

    // Shared memory for weight slice of this co: [Cin, K, K, K]
    extern __shared__ unsigned char smem_raw[];
    T* sW_ptr = reinterpret_cast<T*>(smem_raw);

    const int KKK = K * K * K;
    const int total_w = Cin * KKK;

    Tensor sW = make_tensor(
        make_smem_ptr(sW_ptr),
        make_shape(Cin, K, K, K),
        make_stride(int64_t(KKK), int64_t(K * K), int64_t(K), Int<1>{})
    );

    for (int idx = tid; idx < total_w; idx += Threads) {
        int ci = idx / KKK;
        int rem = idx - ci * KKK;
        int kd = rem / (K * K);
        rem = rem - kd * (K * K);
        int kh = rem / K;
        int kw = rem - kh * K;
        sW(ci, kd, kh, kw) = mW(ci, co, kd, kh, kw);
    }
    __syncthreads();

    float bias_val = 0.0f;
    if (Bs != nullptr) {
        bias_val = (float)Bs[co];
    }

    // Precompute output coordinates for each point handled by this thread
    int p_idx[PVec];
    int od_arr[PVec];
    int oh_arr[PVec];
    int ow_arr[PVec];

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
        int p = p_block + tid + i * Threads;
        p_idx[i] = p;
        if (p < P_total) {
            int od = p / (Hout * Wout);
            int rem = p - od * (Hout * Wout);
            int oh = rem / Wout;
            int ow = rem - oh * Wout;
            od_arr[i] = od;
            oh_arr[i] = oh;
            ow_arr[i] = ow;
        } else {
            od_arr[i] = 0;
            oh_arr[i] = 0;
            ow_arr[i] = 0;
        }
    }

    float acc[PVec];
    #pragma unroll
    for (int i = 0; i < PVec; ++i) acc[i] = bias_val;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
        int p = p_idx[i];
        if (p >= P_total) continue;

        int od = od_arr[i];
        int oh = oh_arr[i];
        int ow = ow_arr[i];

        for (int kd = 0; kd < K; ++kd) {
            int id_num = od + padding - kd;
            if (id_num % stride != 0) continue;
            int id = id_num / stride;
            if (id < 0 || id >= D) continue;

            for (int kh = 0; kh < K; ++kh) {
                int ih_num = oh + padding - kh;
                if (ih_num % stride != 0) continue;
                int ih = ih_num / stride;
                if (ih < 0 || ih >= H) continue;

                for (int kw = 0; kw < K; ++kw) {
                    int iw_num = ow + padding - kw;
                    if (iw_num % stride != 0) continue;
                    int iw = iw_num / stride;
                    if (iw < 0 || iw >= Win) continue;

                    float sum = 0.0f;
                    #pragma unroll 4
                    for (int ci = 0; ci < Cin; ++ci) {
                        float xval = (float)mX(ci, id, ih, iw);
                        float wval = (float)sW(ci, kd, kh, kw);
                        sum += xval * wval;
                    }
                    acc[i] += sum;
                }
            }
        }
    }

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
        int p = p_idx[i];
        if (p >= P_total) continue;
        int od = od_arr[i];
        int oh = oh_arr[i];
        int ow = ow_arr[i];
        mY(od, oh, ow) = static_cast<T>(acc[i]);
    }
}
// Specialized cooperative tiled kernel for stride == 1.
// Uses 2D spatial tiling over (oh, ow) for a fixed (n, co, od), staging
// both the per-co weight slice and the required input tile (with halo)
// into shared memory to eliminate redundant global memory traffic across
// neighboring output points that share overlapping receptive fields.
template <typename T, int TILE_OH, int TILE_OW>
__global__ void convtranspose3d_kernel_s1(
    const T* __restrict__ X,   // [N, Cin, D, H, W]
    const T* __restrict__ Wt,  // [Cin, Cout, K, K, K]
    const T* __restrict__ Bs,  // [Cout] or nullptr
    T* __restrict__ Y,         // [N, Cout, Dout, Hout, Wout]
    int N, int Cin, int D, int H, int Win,
    int Cout, int K, int padding,
    int Dout, int Hout, int Wout,
    int tileCountW,
    int cinChunk)
{
    const int tid = threadIdx.x;
    const int tx = tid % TILE_OW;
    const int ty = tid / TILE_OW;
    const int co = blockIdx.y;
    const int od = blockIdx.z % Dout;
    const int n  = blockIdx.z / Dout;
    const int tileIdxH = blockIdx.x / tileCountW;
    const int tileIdxW = blockIdx.x % tileCountW;
    const int oh0 = tileIdxH * TILE_OH;
    const int ow0 = tileIdxW * TILE_OW;
    const int oh = oh0 + ty;
    const int ow = ow0 + tx;
    const int64_t sXc = (int64_t)D * H * Win;
    const int64_t sXd = (int64_t)H * Win;
    const int64_t sXh = (int64_t)Win;
    const int64_t sXn = (int64_t)Cin * sXc;
    const int64_t sYc = (int64_t)Dout * Hout * Wout;
    const int64_t sYd = (int64_t)Hout * Wout;
    const int64_t sYh = (int64_t)Wout;
    const int64_t sYn = (int64_t)Cout * sYc;
    const T* Xn = X + (int64_t)n * sXn;
    T* Yptr = Y + (int64_t)n * sYn + (int64_t)co * sYc;
    const int64_t sWci = (int64_t)Cout * K * K * K;
    const int64_t sWco = (int64_t)K * K * K;
    const int64_t sWkd = (int64_t)K * K;
    const int64_t sWkh = (int64_t)K;
    extern __shared__ unsigned char smem_raw[];
    T* sW_ptr = reinterpret_cast<T*>(smem_raw);
    const int KKK = K * K * K;
    T* sX_ptr = sW_ptr + cinChunk * KKK;
    const int SH_H = TILE_OH + K - 1;
    const int SH_W = TILE_OW + K - 1;
    const int SHHW = SH_H * SH_W;
    float bias_val = 0.0f;
    if (Bs != nullptr) bias_val = (float)Bs[co];
    float acc = bias_val;
    const int ih_base = oh0 + padding - (K - 1);
    const int iw_base = ow0 + padding - (K - 1);
    // Register-blocked over input channels: process Cin in chunks to
    // shrink the shared-memory footprint per block, allowing more
    // resident blocks per SM (higher occupancy) while still fully
    // reusing the staged input tile / weight slice across the (kh, kw)
    // computation within each chunk.
    for (int ci0 = 0; ci0 < Cin; ci0 += cinChunk) {
        int cur_chunk = min(cinChunk, Cin - ci0);
        int total_w_cur = cur_chunk * KKK;
        for (int idx = tid; idx < total_w_cur; idx += blockDim.x) {
            int ci = idx / KKK;
            int rem = idx - ci * KKK;
            int kd = rem / (K * K);
            rem -= kd * (K * K);
            int kh = rem / K;
            int kw = rem - kh * K;
            int64_t wsrc = (int64_t)(ci0 + ci) * sWci + (int64_t)co * sWco +
                            (int64_t)kd * sWkd + (int64_t)kh * sWkh + kw;
            sW_ptr[idx] = Wt[wsrc];
        }
        __syncthreads();
        for (int kd = 0; kd < K; ++kd) {
            int id = od + padding - kd;
            bool id_valid = (id >= 0 && id < D);
            int total_x_cur = cur_chunk * SHHW;
            for (int idx = tid; idx < total_x_cur; idx += blockDim.x) {
                int ci = idx / SHHW;
                int rem = idx - ci * SHHW;
                int sh = rem / SH_W;
                int sw = rem - sh * SH_W;
                float val = 0.0f;
                if (id_valid) {
                    int ih = ih_base + sh;
                    int iw = iw_base + sw;
                    if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
                        int64_t xsrc = (int64_t)(ci0 + ci) * sXc + (int64_t)id * sXd +
                                        (int64_t)ih * sXh + iw;
                        val = (float)Xn[xsrc];
                    }
                }
                sX_ptr[idx] = (T)val;
            }
            __syncthreads();
            if (id_valid && oh < Hout && ow < Wout) {
                for (int kh = 0; kh < K; ++kh) {
                    int ih = oh + padding - kh;
                    if (ih < 0 || ih >= H) continue;
                    int sh = ih - ih_base;
                    for (int kw = 0; kw < K; ++kw) {
                        int iw = ow + padding - kw;
                        if (iw < 0 || iw >= Win) continue;
                        int sw = iw - iw_base;
                        float sum = 0.0f;
                        #pragma unroll 4
                        for (int ci = 0; ci < cur_chunk; ++ci) {
                            float xval = (float)sX_ptr[ci * SHHW + sh * SH_W + sw];
                            float wval = (float)sW_ptr[ci * KKK + kd * K * K + kh * K + kw];
                            sum += xval * wval;
                        }
                        acc += sum;
                    }
                }
            }
            __syncthreads();
        }
    }
    if (oh < Hout && ow < Wout) {
        int64_t ydst = (int64_t)od * sYd + (int64_t)oh * sYh + ow;
        Yptr[ydst] = static_cast<T>(acc);
    }
}

torch::Tensor convtranspose3d_forward(torch::Tensor x,
                                       torch::Tensor weight,
                                       c10::optional<torch::Tensor> bias,
                                       int stride, int padding, int output_padding,
                                       int groups) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    if (bias.has_value()) TORCH_CHECK(bias.value().is_cuda(), "bias must be CUDA if provided");

    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    if (bias.has_value()) TORCH_CHECK(bias.value().scalar_type() == at::kFloat, "bias must be float32");

    TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, D, H, W]");
    TORCH_CHECK(weight.dim() == 5, "weight must be [Cin, Cout, K, K, K]");
    TORCH_CHECK(groups == 1, "only groups=1 supported");

    int64_t N   = x.size(0);
    int64_t Cin = x.size(1);
    int64_t D   = x.size(2);
    int64_t H   = x.size(3);
    int64_t Win = x.size(4);

    TORCH_CHECK(weight.size(0) == Cin, "weight.size(0) must equal Cin");
    int64_t Cout = weight.size(1);
    int64_t K    = weight.size(2);
    TORCH_CHECK(weight.size(3) == K && weight.size(4) == K, "weight must have cube kernel");

    TORCH_CHECK(stride > 0, "stride must be > 0");
    TORCH_CHECK(padding >= 0, "padding must be >= 0");
    TORCH_CHECK(output_padding >= 0, "output_padding must be >= 0");

    int64_t Dout = (D - 1) * stride - 2 * padding + K + output_padding;
    int64_t Hout = (H - 1) * stride - 2 * padding + K + output_padding;
    int64_t Wout = (Win - 1) * stride - 2 * padding + K + output_padding;
    TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();

    torch::Tensor b_c;
    const float* b_ptr = nullptr;
    if (bias.has_value()) {
        b_c = bias.value().contiguous();
        TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
        b_ptr = b_c.data_ptr<float>();
    }

    auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

    constexpr int Threads = 128;
    constexpr int PVec = 4;
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    if (stride == 1) {
        constexpr int TILE_OH = 8;
        constexpr int TILE_OW = 16;
        const int tileCountW = (int)((Wout + TILE_OW - 1) / TILE_OW);
        const int tileCountH = (int)((Hout + TILE_OH - 1) / TILE_OH);
        dim3 block(TILE_OH * TILE_OW);
        dim3 grid(
            (unsigned)(tileCountW * tileCountH),
            (unsigned)Cout,
            (unsigned)(N * Dout)
        );
        const int SH_H = TILE_OH + (int)K - 1;
        const int SH_W = TILE_OW + (int)K - 1;
        int cinChunk = (Cin < 8) ? (int)Cin : 8;
        if (cinChunk <= 0) cinChunk = 1;
        size_t smem_bytes = ((size_t)cinChunk * K * K * K + (size_t)cinChunk * SH_H * SH_W) * sizeof(float);
        convtranspose3d_kernel_s1<float, TILE_OH, TILE_OW><<<grid, block, smem_bytes, stream>>>(
            x_c.data_ptr<float>(),
            w_c.data_ptr<float>(),
            b_ptr,
            y.data_ptr<float>(),
            (int)N, (int)Cin, (int)D, (int)H, (int)Win,
            (int)Cout, (int)K, (int)padding,
            (int)Dout, (int)Hout, (int)Wout,
            tileCountW,
            cinChunk
        );
    } else {
        const int64_t P_total = Dout * Hout * Wout;
        const int64_t PTile = Threads * PVec;
        dim3 block(Threads);
        dim3 grid(
            (unsigned)((P_total + PTile - 1) / PTile),
            (unsigned)Cout,
            (unsigned)N
        );
        size_t smem_bytes = (size_t)Cin * K * K * K * sizeof(float);
        convtranspose3d_kernel<float, Threads, PVec><<<grid, block, smem_bytes, stream>>>(
            x_c.data_ptr<float>(),
            w_c.data_ptr<float>(),
            b_ptr,
            y.data_ptr<float>(),
            (int)N, (int)Cin, (int)D, (int)H, (int)Win,
            (int)Cout, (int)K, (int)stride, (int)padding,
            (int)Dout, (int)Hout, (int)Wout
        );
    }
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "convtranspose3d_kernel launch failed: ", cudaGetErrorString(err));
    return y;
}
"""

conv_ext = load_inline(
    name="cute_convtranspose3d_ext",
    cpp_sources=cuda_decl,
