            __syncthreads();
            if (id_valid && oh < Hout) {
                for (int kh = 0; kh < K; ++kh) {
                    int ih = oh + padding - kh;
                    if (ih < 0 || ih >= H) continue;
                    int sh = ih - ih_base;
                    for (int kw = 0; kw < K; ++kw) {
                        int sw_arr[WPT];
                        bool valid_arr[WPT];
                        #pragma unroll
                        for (int r = 0; r < WPT; ++r) {
